import math
from fractions import Fraction

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def phi(n):
    if n == 1:
        return 1
    factors = prime_factorization(n)
    result = n
    for p in factors:
        result = result * (p - 1) // p
    return result

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

